const incoming=$json.body??$json;
const batchId=incoming.batchId||incoming.jobId||('gen-'+Date.now());
const productName=incoming.productName||incoming.product?.name||'Товар';
const brief=String(incoming.brief||incoming.generationPrompt||'').trim();

const all=[
  ...(Array.isArray(incoming.avatarReferences)?incoming.avatarReferences:[]),
  ...(Array.isArray(incoming.media)?incoming.media:[]),
  ...(Array.isArray(incoming.product?.media)?incoming.product.media:[])
];

const refs=[];
const seen=new Set();
for(const item of all){
  const url=typeof item==='string'?item:(item?.url||item?.publicUrl||'');
  if(typeof url!=='string'||!url.startsWith('https://')||seen.has(url)) continue;
  seen.add(url); refs.push(url);
  if(refs.length>=9) break;
}

const prompt=brief || [
  'Vertical 9:16 realistic product video.',
  'Show the real product clearly and preserve its actual shape, color and construction.',
  'Product: '+productName+'.',
  'Natural commercial lighting, believable motion, clean mobile-first composition.',
  'Do not invent specifications or features.'
].join(' ');

return [{json:{
  batchId,
  jobId:incoming.jobId||batchId,
  productName,
  prompt,
  referenceMedia:refs,
  duration:5,
  aspectRatio:'9:16',
  resolution:'720p',
  generateAudio:true,
  receivedAt:new Date().toISOString()
}}];

const base=$('Подготовить тестовую сцену').item.json;
const result=$json||{};
const failed=Boolean(result.error)&&!result.urls;
return [{json:{
  batchId:base.batchId,
  jobId:base.jobId,
  ok:!failed && result.ok!==false,
  result,
  error:failed?String(result.error||result.message||'Generation failed'):null,
  completedAt:new Date().toISOString()
}}];
